package linter

import (
	"os"
	"path/filepath"
	"testing"

	gofinding "github.com/larsartmann/go-finding"
)

// generatedFileTests pins the generated-file skip: files carrying the
// ecosystem-standard "Code generated ... DO NOT EDIT." header are neither
// linted (BD001 + BD003) nor repaired, restoring the excludeGenerated
// default of the rule's branching-flow ancestor (parity gap found on CV's
// sqlc/templ output, 2026-10-11).
func TestGeneratedFilesAreSkipped(t *testing.T) {
	t.Parallel()

	t.Run("sqlc header silences BD003", func(t *testing.T) {
		t.Parallel()

		src := "// Code generated by sqlc. DO NOT EDIT.\n" +
			"// versions:\n" +
			"//   sqlc v1.31.1\n" +
			"package db\n\n" +
			"type Params struct {\n\tSessionID string\n}\n"

		assertFindings(t, detectSourceRules(t, src, bd003Only()), nil, nil)
	})

	t.Run("templ header silences BD003", func(t *testing.T) {
		t.Parallel()

		src := "// Code generated by templ - DO NOT EDIT.\n\n" +
			"package ui\n\n" +
			"func statCard(containerID string) {}\n"

		assertFindings(t, detectSourceRules(t, src, bd003Only()), nil, nil)
	})

	t.Run("protoc-gen header silences BD001", func(t *testing.T) {
		t.Parallel()

		src := "// Code generated by protoc-gen-go. DO NOT EDIT.\n" +
			"package pb\n\n" +
			"type UserBrand struct{}\n\n" +
			"func use() { _ = id.ID[UserBrand, string]{} }\n"

		assertFindings(t, detectSourceRules(t, src, DefaultRuleSet()), nil, nil)
	})

	t.Run("same content without header still fires", func(t *testing.T) {
		t.Parallel()

		src := "package db\n\ntype Params struct {\n\tSessionID string\n}\n"

		assertFindings(
			t,
			detectSourceRules(t, src, bd003Only()),
			[]gofinding.RuleName{RuleIDBD003},
			[]string{"'SessionID'"},
		)
	})

	t.Run("generated-looking comment after the package clause does not skip", func(t *testing.T) {
		t.Parallel()

		src := "package db\n\n" +
			"// Code generated by hand. DO NOT EDIT.\n" +
			"type Guarded struct{}\n\n" +
			"type Params struct {\n\tSessionID string\n}\n"

		assertFindings(
			t,
			detectSourceRules(t, src, bd003Only()),
			[]gofinding.RuleName{RuleIDBD003},
			[]string{"'SessionID'"},
		)
	})

	t.Run("repair never inserts into a generated file", func(t *testing.T) {
		t.Parallel()

		src := "// Code generated by sqlc. DO NOT EDIT.\n" +
			"package db\n\n" +
			"type UserBrand struct{}\n\n" +
			"func use() { _ = id.ID[UserBrand, string]{} }\n"

		filename := writeTestFile(t, t.TempDir(), src)

		inserted, err := RepairPath(filepath.Dir(filename))
		if err != nil {
			t.Fatalf("RepairPath() error = %v", err)
		}

		if inserted != 0 {
			t.Errorf("RepairPath() inserted %d stubs into generated files, want 0", inserted)
		}

		after, readErr := os.ReadFile(filename)
		if readErr != nil {
			t.Fatalf("ReadFile() error = %v", readErr)
		}

		if string(after) != src {
			t.Errorf("generated file was rewritten:\n%s", string(after))
		}
	})
}
